    global activation_count, prev_target_pos, cooldown_remaining, last_thrust_time, target_speed_threshold

    # Initialize state if not already done
    if 'activation_count' not in globals():
        activation_count = 0
        prev_target_pos = None
        cooldown_remaining = 0
        last_thrust_time = step_count
        target_speed_threshold = 0.15

    seeker_pos = sandbox.get_seeker_position()
    seeker_vel = sandbox.get_seeker_velocity()
    current_heading = sandbox.get_seeker_heading()
    x_min, x_max = sandbox.get_corridor_bounds()
    budget = sandbox.get_remaining_impulse_budget()

    # Update activation count
    if x_min - 0.02 <= seeker_pos[0] <= x_max + 0.02:
        activation_count += 1
        if seeker_pos[0] < 13.0 or seeker_pos[0] > 17.0:
            activation_count = 0
    else:
        activation_count = 0

