    activated = activation_count >= 80

    # Check if in rendezvous slot
    slots = sandbox.get_rendezvous_slots()
    in_rendezvous_slot = any(slot[0] <= step_count <= slot[1] for slot in slots)

    # Handle activation phase
    if not activated:
        # Move towards activation zone
        if seeker_pos[0] < 13.0:
            desired_x = 13.0
        elif seeker_pos[0] > 17.0:
            desired_x = 17.0
        else:
            desired_x = seeker_pos[0]

